var grid_size=30,grid_reference=[];function get_cell(e,o){return grid_reference[o][e]}function get_cell_tuple(e){return get_cell(e[0],e[1])}function copy_tuple(e){return[e[0],e[1]]}var table=document.getElementById("grid");if(null==table)throw new Error("Unable to get grid");for(var y=0;y<grid_size;y++){var row=document.createElement("tr");grid_reference[y]=[];for(var x=0;x<grid_size;x++){var cell=document.createElement("td");cell.setAttribute("class","cell empty-cell"),row.appendChild(cell),grid_reference[y][x]=cell}table.appendChild(row)}var body=[[Math.floor(grid_size/2),Math.floor(grid_size/2)]],food=[];function make_food(){for(var e=-1,o=-1;;){for(var r=Math.round(Math.random()*(grid_size-1)),t=Math.round(Math.random()*(grid_size-1)),d=!0,l=0,i=body;l<i.length;l++){var a=i[l];if(a[0]==r&&a[1]==t){d=!1;break}}if(d)for(var n=0,c=food;n<c.length;n++){var _=c[n];if(_[0]==r&&_[1]==t){d=!1;break}}if(d){e=r,o=t;break}}if(e<0||o<0)throw new Error("Should be unreachable");var b=[e,o],b=get_cell_tuple(food[food.length]=b);b.setAttribute("class","cell food-cell"),b.setAttribute("class","cell food-cell")}var direction=2,last_direction=direction,game_over=!1;function do_game_over(){game_over=!0}function step(){if(!game_over){for(var e=get_cell_tuple(body[body.length-1]),o=[copy_tuple(body[0])],r=1;r<body.length;r++)o[r]=copy_tuple(body[r-1]);var t=(body=o)[0];switch(direction){case 0:body[0]=[t[0],t[1]+1];break;case 1:body[0]=[t[0]+1,t[1]];break;case 2:body[0]=[t[0],t[1]-1];break;case 3:body[0]=[t[0]-1,t[1]]}for(r=1;r<body.length;r++)if(body[0][0]==body[r][0]&&body[0][1]==body[r][1])return void do_game_over();if(body[0][0]<0||body[0][0]>grid_size-1||body[0][1]<0||body[0][1]>grid_size-1)do_game_over();else{var d=get_cell_tuple(body[0]);if(d){d.setAttribute("class","cell snake-cell"),e&&e.setAttribute("class","cell empty-cell"),last_direction=direction;for(r=0;r<food.length;r++){var l=food[r];body[0][0]==l[0]&&body[0][1]==l[1]&&(body[body.length]=copy_tuple(body[body.length-1]),make_food(),food.splice(r,1))}}else do_game_over()}}}document.onkeydown=function(e){"s"==e.key&&2!=last_direction?direction=0:"d"==e.key&&3!=last_direction?direction=1:"w"==e.key&&0!=last_direction?direction=2:"a"==e.key&&1!=last_direction&&(direction=3)};for(var i=0;i<10;i++)make_food();setInterval(function(){step()},100);